\begin{prop}
\ollabel{prop:formed}
Every !!{formula}~$!A$ in~$\Frm[L_0]$ has a formation sequence.
\end{prop}

\begin{proof}
Suppose $!A$ is atomic. Then the sequence~$\tuple{!A}$ is a
formation sequence for~$!A$.
%
Now suppose that $!B$ and~$!C$ have formation sequences
$\tuple{!B_0,\dotsc,!B_n}$ and $\tuple{!C_0,\dotsc,!C_m}$
respectively.
%
\begin{enumerate}
  \tagitem{prvNot}{If $!A \ident \lnot !B$,
      then $\tuple{!B_0,\dotsc,!B_n,\lnot !B_n}$
      is a formation sequence for~$!A$.}{}
  \tagitem{prvAnd}{If $!A \ident (!B \land !C)$,
      then $\tuple{!B_0,\dotsc,!B_n,!C_0,\dotsc,!C_m,(!B_n \land !C_m)}$
      is a formation sequence for~$!A$.}{}
  \tagitem{prvOr}{If $!A \ident (!B \lor !C)$,
      then $\tuple{!B_0,\dotsc,!B_n,!C_0,\dotsc,!C_m,(!B_n \lor !C_m)}$
      is a formation sequence for~$!A$.}{}
  \tagitem{prvIf}{If $!A \ident (!B \lif !C)$,
      then $\tuple{!B_0,\dotsc,!B_n,!C_0,\dotsc,!C_m,(!B_n \lif !C_m)}$
      is a formation sequence for~$!A$.}{}
  \tagitem{prvIff}{If $!A \ident (!B \liff !C)$,
      then $\tuple{!B_0,\dotsc,!B_n,!C_0,\dotsc,!C_m,(!B_n \liff !C_m)}$
      is a formation sequence for~$!A$.}{}
\end{enumerate}
By the principle of induction on !!{formula}s,
every !!{formula} has a formation sequence.
\end{proof}

target_text:
\begin{prop}
\ollabel{prop:formed}
Toute !!{formula}~$!A$ de~$\Frm[L_0]$ admet une suite de formation.
\end{prop}

\begin{proof}
Supposons $!A$ atomique. Alors la suite~$\tuple{!A}$ est une suite
de formation de~$!A$.
%
Supposons maintenant que $!B$ et~$!C$ admettent respectivement les
suites de formation $\tuple{!B_0,\dotsc,!B_n}$ et
$\tuple{!C_0,\dotsc,!C_m}$.
%
\begin{enumerate}
  \tagitem{prvNot}{Si $!A \ident \lnot !B$,
      alors $\tuple{!B_0,\dotsc,!B_n,\lnot !B_n}$
      est une suite de formation de~$!A$.}{}
  \tagitem{prvAnd}{Si $!A \ident (!B \land !C)$,
      alors $\tuple{!B_0,\dotsc,!B_n,!C_0,\dotsc,!C_m,(!B_n \land !C_m)}$
      est une suite de formation de~$!A$.}{}
  \tagitem{prvOr}{Si $!A \ident (!B \lor !C)$,
      alors $\tuple{!B_0,\dotsc,!B_n,!C_0,\dotsc,!C_m,(!B_n \lor !C_m)}$
      est une suite de formation de~$!A$.}{}
  \tagitem{prvIf}{Si $!A \ident (!B \lif !C)$,
      alors $\tuple{!B_0,\dotsc,!B_n,!C_0,\dotsc,!C_m,(!B_n \lif !C_m)}$
      est une suite de formation de~$!A$.}{}
  \tagitem{prvIff}{Si $!A \ident (!B \liff !C)$,
      alors $\tuple{!B_0,\dotsc,!B_n,!C_0,\dotsc,!C_m,(!B_n \liff !C_m)}$
      est une suite de formation de~$!A$.}{}
\end{enumerate}
Le principe d'induction sur les !!{formula}s permet de conclure que
toute !!{formula} admet une suite de formation.
\end{proof}

